use std::io::{self, Read};
fn mn(a: i32, b: i32) -> i32 {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32 {
    a.max(b)
}
fn emit(x: i32) {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32) {
    if n == 0 {
        print!("-");
    }
    for i in 0..n {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader {
    t: Vec<String>,
    p: usize,
}
impl Reader {
    fn new() -> Self {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self {
            t: s.split_whitespace().map(String::from).collect(),
            p: 0,
        }
    }
    fn read(&mut self) -> i32 {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32 {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-" {
            return 0;
        }
        for (i, c) in s.bytes().enumerate() {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main() {
    let mut reader = Reader::new();
    let mut a = vec![0i32; 20000];
    let mut b = vec![0i32; 20000];
    let mut d = vec![0i32; 20000];
    let mut e = vec![0i32; 20000];
    let mut best: i32 = 0;
    let mut i: i32 = 0;
    let mut k: i32 = 0;
    let mut left: i32 = 0;
    let mut length: i32 = 0;
    let mut n: i32 = 0;
    let mut right: i32 = 0;
    let mut width: i32 = 0;
    n = reader.read();
    a[(0) as usize] = 1;
    a[(n + 1) as usize] = 1;
    i = 1;
    while i < (n + 1) {
        a[(i) as usize] = reader.read();
        i += 1;
    }
    width = (n + 2);
    length = 2;
    while length < (n + 2) {
        left = 0;
        while left < ((n + 2) - length) {
            right = (left + length);
            best = 0;
            k = (left + 1);
            while k < right {
                best = mx(
                    best,
                    ((d[((left * width) + k) as usize] + d[((k * width) + right) as usize])
                        + ((a[(left) as usize] * a[(k) as usize]) * a[(right) as usize])),
                );
                k += 1;
            }
            d[((left * width) + right) as usize] = best;
            left += 1;
        }
        length += 1;
    }
    emit(d[(n + 1) as usize]);
}
